import assert from 'node:assert/strict';
import {test} from 'node:test';
import {verifyPassword, safeReturnPath} from '../src/common/credentials';

// Independently generated by the existing Python hashlib.scrypt implementation.
const legacy =
  '000102030405060708090a0b0c0d0e0f:089422f08af6b623ad2fb74fb1ff842b6eb7aa3d41155b3d2646420f8db7a033ac4e66b276ca4fd87805e3bd3596933d13d6c8657f2fd18f8d3e787f57b251a7';

test('existing Python password hash authenticates without rehashing or resetting it', async () => {
  assert.equal(await verifyPassword('compatibility-password', legacy), true);
  assert.equal(await verifyPassword('wrong-password', legacy), false);
  assert.equal(await verifyPassword('compatibility-password', null), false);
  assert.equal(await verifyPassword('compatibility-password', 'broken:hash'), false);
});

test('OAuth return path keeps local editor context and rejects external redirects', () => {
  assert.equal(safeReturnPath('/cvs/abc?tab=preview'), '/cvs/abc?tab=preview');
  for (const path of [
    'https://evil.example',
    '//evil.example',
    '/\\evil.example',
    '/%2f%2fevil.example',
    '/\r\nLocation:evil',
  ]) {
    assert.equal(safeReturnPath(path), '/');
  }
});
